package com.rpsbattle.tournament;
import com.rpsbattle.tournament.domain.*;import com.rpsbattle.account.*;import com.rpsbattle.account.domain.*;import com.rpsbattle.auth.*;import com.rpsbattle.online.*;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class ReadyCheckTest {
 final Instant now=Instant.parse("2026-10-15T10:00:00Z");final TournamentService tournaments=mock(TournamentService.class);final OwnedTournamentService owned=mock(OwnedTournamentService.class);final AccountAuthorizationService accounts=mock(AccountAuthorizationService.class);final OnlineMatchService online=mock(OnlineMatchService.class);
 TournamentReadyService service(){doAnswer(call->{call.<Runnable>getArgument(1).run();return null;}).when(owned).systemMutation(any(),any());return new TournamentReadyService(tournaments,owned,accounts,online,Clock.fixed(now,ZoneOffset.UTC),30);}
 Tournament cup(boolean bot){var t=new Tournament(UUID.randomUUID().toString(),"Ready",TournamentFormat.ROUND_ROBIN,now);t.status=TournamentStatus.RUNNING;var a=new TournamentParticipant(UUID.randomUUID().toString(),null,"","Human A",1,UUID.randomUUID());var b=new TournamentParticipant(UUID.randomUUID().toString(),bot?UUID.randomUUID().toString():null,"","Opponent",2,UUID.randomUUID());t.participants.addAll(List.of(a,b));t.matches.add(new TournamentMatch(UUID.randomUUID().toString(),t.id,a,b));when(tournaments.find(t.id)).thenReturn(t);return t;}
 @Test void botsAutoConfirmHumansUseStableWindowAndDuplicatesDoNotCreateRooms(){var ready=service();var t=cup(true);var m=t.matches.getFirst();assertThat(ready.permit(t,m)).isFalse();var window=t.readyWindows.get(m.id);assertThat(window.confirmed()).containsExactly(m.participantB.participantId());var user=new User(new UserId(m.participantA.ownerUserId()),"ready","ready@example.invalid","fixture","Ready",UserRole.USER,AccountStatus.ACTIVE,now,now,null,0);var auth=AuthService.sessionAuthentication(user);when(accounts.requireUser(auth)).thenReturn(user);
  assertThatThrownBy(()->ready.ready(auth,t.id,m.id,"old-window")).isInstanceOf(AuthException.class);ready.ready(auth,t.id,m.id,window.id());ready.ready(auth,t.id,m.id,window.id());assertThat(ready.permit(t,m)).isTrue();assertThat(t.operations.audit().stream().filter(e->e.type().equals("MATCH_PARTICIPANT_READY"))).hasSize(1);verifyNoInteractions(online);
 }
 @Test void doubleNoShowUsesExistingDoubleForfeitWithoutInventingPlayedGame(){var ready=service();var t=cup(false);var m=t.matches.getFirst();t.readyWindows.put(m.id,new MatchReadyWindow("expired",now.minusSeconds(1),Set.of()));assertThat(ready.permit(t,m)).isFalse();assertThat(m.status).isEqualTo(TournamentMatch.Status.FINISHED);assertThat(m.decisionReason).isEqualTo("DOUBLE_FORFEIT");assertThat(m.winnerParticipantId).isNull();assertThat(m.historyMatchId).isNull();verifyNoInteractions(online);}
 @Test void onlyConfirmedSideWinsNoShowAndPausedWindowsNeverAdmit(){var ready=service();var t=cup(true);var m=t.matches.getFirst();t.readyWindows.put(m.id,new MatchReadyWindow("expired",now.minusSeconds(1),Set.of(m.participantB.participantId())));t.status=TournamentStatus.PAUSED;assertThat(ready.permit(t,m)).isFalse();assertThat(m.status).isEqualTo(TournamentMatch.Status.PENDING);t.status=TournamentStatus.RUNNING;ready.permit(t,m);assertThat(m.winnerParticipantId).isEqualTo(m.participantB.participantId());assertThat(m.failure).isEqualTo("NO_SHOW");}
}
